CREATE TABLE recipe_versions (
  id TEXT PRIMARY KEY NOT NULL,
  domain TEXT NOT NULL,
  version INTEGER NOT NULL,
  script TEXT NOT NULL,
  created_at TEXT NOT NULL,
  CONSTRAINT uq_recipe_versions_domain_version UNIQUE (domain, version)
);

CREATE TABLE items (
  id TEXT PRIMARY KEY NOT NULL,
  url TEXT NOT NULL,
  title TEXT,
  status TEXT NOT NULL CHECK (status IN ('queued','generating','ready','failed')),
  voice TEXT NOT NULL,
  created_at TEXT NOT NULL,
  duration REAL,
  audio_format TEXT,
  units TEXT CHECK (units IS NULL OR json_valid(units)),
  error TEXT,
  modal_call_id TEXT,
  queued_at TEXT,
  enriched_at TEXT,
  retry_count INTEGER,
  degradations TEXT CHECK (degradations IS NULL OR json_valid(degradations)),
  extraction_handle TEXT,
  extraction_domain TEXT,
  recipe_version_id TEXT REFERENCES recipe_versions (id)
);

CREATE TABLE cost_entries (
  id TEXT PRIMARY KEY NOT NULL,
  item_id TEXT NOT NULL REFERENCES items (id),
  type TEXT NOT NULL,
  quantity REAL NOT NULL,
  unit TEXT NOT NULL,
  dollars REAL NOT NULL,
  detail TEXT CHECK (detail IS NULL OR json_valid(detail))
);
EOF
cat > migrations/0002_add_priority.sql <<'EOF'
ALTER TABLE items ADD COLUMN priority INTEGER;
EOF
cat > src/index.ts <<'EOF'
interface Env {
  DB: D1Database;
  WORKER_NAME: string;
}

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    const id = url.searchParams.get("id") ?? "";
    const who = env.WORKER_NAME;

    if (url.pathname === "/seed") {
      const now = new Date().toISOString();
      const units = JSON.stringify([{ kind: "text", display: "Hello **world**", spoken: "Hello world" }]);
      await env.DB.prepare(
        "INSERT INTO items (id, url, status, voice, created_at, queued_at, units) VALUES (?1, 'https://example.com/a', 'queued', 'af_heart', ?2, ?2, ?3)",
      ).bind(id, now, units).run();
      return json({ who, seeded: id });
    }

    if (url.pathname === "/claim") {
      const t0 = Date.now();
      const r = await env.DB.prepare(
        "UPDATE items SET status = 'generating', error = ?2 WHERE id = ?1 AND status = 'queued'",
      ).bind(id, `claimed-by-${who}`).run();
      return json({ who, id, changes: r.meta.changes, rows_written: r.meta.rows_written, served_by_primary: r.meta.served_by_primary, ms: Date.now() - t0 });
    }

    if (url.pathname === "/retry-claim") {
      const r = await env.DB.prepare(
        "UPDATE items SET status = 'queued', retry_count = COALESCE(retry_count, 0) + 1, error = NULL WHERE id = ?1 AND status = 'failed' AND (retry_count IS NULL OR retry_count < 3)",
      ).bind(id).run();
      return json({ who, id, changes: r.meta.changes });
    }

    if (url.pathname === "/fail") {
      const r = await env.DB.prepare("UPDATE items SET status = 'failed' WHERE id = ?1").bind(id).run();
      return json({ who, changes: r.meta.changes });
    }

    if (url.pathname === "/get") {
      const row = await env.DB.prepare("SELECT * FROM items WHERE id = ?1").bind(id).first<Record<string, unknown>>();
      if (row == null) return json({ who, row: null }, 404);
      const parsedUnits = row.units == null ? null : JSON.parse(row.units as string);
      return json({ who, row: { ...row, units: parsedUnits }, unitsRawType: typeof row.units });
    }

    if (url.pathname === "/set-units") {
      const body = await req.text();
      const r = await env.DB.prepare("UPDATE items SET units = ?2 WHERE id = ?1").bind(id, body).run();
      return json({ who, changes: r.meta.changes });
    }

    if (url.pathname === "/json-query") {
      const r = await env.DB.prepare(
        "SELECT id, json_extract(units, '$[0].spoken') AS first_spoken, json_array_length(units) AS n FROM items WHERE id = ?1",
      ).bind(id).first();
      return json({ who, r });
    }

    if (url.pathname === "/read-loop") {
      const n = Number(url.searchParams.get("n") ?? "50");
      const out: { i: number; ok: boolean; ms: number; err?: string }[] = [];
      for (let i = 0; i < n; i++) {
        const t0 = Date.now();
        try {
          await env.DB.prepare("SELECT id, status, units FROM items WHERE id = ?1").bind(id).first();
          out.push({ i, ok: true, ms: Date.now() - t0 });
        } catch (e) {
          out.push({ i, ok: false, ms: Date.now() - t0, err: String(e) });
        }
      }
      const failures = out.filter((o) => !o.ok);
      const ms = out.map((o) => o.ms).sort((a, b) => a - b);
      return json({ who, n, failures: failures.length, firstFailure: failures[0] ?? null, p50: ms[Math.floor(n / 2)], max: ms[n - 1] });
    }

    if (url.pathname === "/uses-priority") {
      try {
        const r = await env.DB.prepare("SELECT id, priority FROM items WHERE id = ?1").bind(id).first();
        return json({ who, ok: true, r });
      } catch (e) {
        return json({ who, ok: false, error: String(e) }, 500);
      }
    }

    if (url.pathname === "/insert-with-priority") {
      try {
        const now = new Date().toISOString();
        const r = await env.DB.prepare(
          "INSERT INTO items (id, url, status, voice, created_at, priority) VALUES (?1, 'u', 'queued', 'v', ?2, 5)",
        ).bind(id, now).run();
        return json({ who, ok: true, changes: r.meta.changes });
      } catch (e) {
        return json({ who, ok: false, error: String(e) }, 500);
      }
    }

    if (url.pathname === "/insert-no-priority") {
      try {
        const now = new Date().toISOString();
        const r = await env.DB.prepare(
          "INSERT INTO items (id, url, status, voice, created_at) VALUES (?1, 'u', 'queued', 'v', ?2)",
        ).bind(id, now).run();
        return json({ who, ok: true, changes: r.meta.changes });
      } catch (e) {
        return json({ who, ok: false, error: String(e) }, 500);
      }
    }

    if (url.pathname === "/bad-status") {
      try {
        await env.DB.prepare("UPDATE items SET status = 'READY' WHERE id = ?1").bind(id).run();
        return json({ who, ok: true });
      } catch (e) {
        return json({ who, ok: false, error: String(e) });
      }
    }

    return json({ who, routes: "seed claim retry-claim fail get set-units json-query read-loop uses-priority insert-with-priority insert-no-priority bad-status" });
  },
};
EOF
